mapper.insert:
/* saleson.shop.orderagency.OrderAgencyMapper.insertAgencyLoginConfirmInfo 대행 주문 로그인 정보 저장 */

INSERT INTO G_AGENCY_LOGIN_CONFIRM_INFO
(
	USER_SESSION_ID
	, VALID_ACCESS_CD
	, MANAGER_ID
	, CNTRBTR_MOBILE
	, PRIVATE_KEY
)
VALUE
(
	#{userSessionId}
	, #{validAccessCd}
	, #{managerId}
	, CRYPTO_ENC('normal', #{cntrbtrMobile}, '')
	, #{privateKey}
)

mapper.delete:

/* saleson.shop.orderagency.OrderAgencyMapper.deleteAgencyLoginConfirmInfo 대행 주문 로그인 정보 삭제 */

DELETE G_AGENCY_LOGIN_CONFIRM_INFO
WHERE MANAGER_ID = #{managerId}

mapper.update:

/* saleson.shop.orderagency.OrderAgencyMapper.updateCntrbtrMobileInfo 대행주문 로그인 정보 기부자 아이디 추가 */
UPDATE G_AGENCY_LOGIN_CONFIRM_INFO
	SET CNTRBTR_ID = #{cntrbtrId}
WHERE 1=1
AND USER_SESSION_ID = #{userSessionId}
AND VALID_ACCESS_CD = #{validAccessCd}

mapper.select:
/* saleson.shop.orderagency.OrderAgencyMapper.selectOrderAgencyOrderList 대행주문 목록 조회 */ SELECT LOCGOV_NM , DATE_FORMAT(STR_TO_DATE(PAY_DATE, '%Y%m%d%H%i%S'), '%Y-%m-%d %H:%i:%S') AS PAY_DATE , ORDER_CODE , CRYPTO_DEC('normal', BUYER_NAME, '', 0) AS BUYER_NAME , CRYPTO_DEC('normal', RECEIVE_NAME, '', 0) AS RECEIVE_NAME , ITEM_NAME , CRYPTO_DEC('normal', MANAGER_NM, '', 0) AS MANAGER_NM , MANAGER_ID , PBADMS_WLFR_CNTR_NM FROM (
SELECT L.UPPER_LOCGOV_NM || ' ' || L.LOCGOV_NM AS LOCGOV_NM , OI.PAY_DATE , OI.ORDER_CODE , O.BUYER_NAME , OSI.RECEIVE_NAME , OI.ITEM_NAME , OAOL.MANAGER_NM , OAOL.MANAGER_ID , CASE WHEN OAOL.PBADMS_WLFR_CNTR_ID > 0 THEN LPWCM.PBADMS_WLFR_CNTR_NM ELSE R.ROLE_NAME END AS PBADMS_WLFR_CNTR_NM FROM G_ORDER_AGENCY_ORDER_LOG OAOL LEFT JOIN OP_ORDER O ON OAOL.ORDER_CODE = O.ORDER_CODE LEFT JOIN OP_ORDER_ITEM OI ON OI.ORDER_CODE = OAOL.ORDER_CODE AND OI.ORDER_SEQUENCE = OAOL.ORDER_SEQUENCE AND OI.ITEM_SEQUENCE = OAOL.ITEM_SEQUENCE LEFT JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE LEFT JOIN G_LOCGOV L ON OAOL.MANAGER_LCLGV_CD = L.LOCGOV_CODE LEFT JOIN OP_USER_ROLE UR ON OAOL.MANAGER_ID = UR.USER_ID AND UR.AUTHORITY LIKE 'ROLE_ADMIN_%' AND UR.AUTHORITY != 'ROLE_ADMIN_CALL' LEFT JOIN OP_ROLE R ON UR.AUTHORITY = R.AUTHORITY LEFT JOIN G_LCLGV_PBADMS_WLFR_CNTR_MNG LPWCM ON LPWCM.PBADMS_WLFR_CNTR_ID = OAOL.PBADMS_WLFR_CNTR_ID WHERE 1=1
AND OAOL.MANAGER_ID = #{userId}
AND OI.PAY_DATE BETWEEN #{searchStartDate} || '000000' AND #{searchEndDate} || '235959'
AND OAOL.MANAGER_LCLGV_CD = #{locgovCode}
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND OAOL.MANAGER_LCLGV_CD = #{locgovCode}
AND OAOL.ORDER_CODE LIKE '%' || #{query} || '%'
AND O.BUYER_NAME = (CRYPTO_ENC('normal', #{query}, ''))
AND OSI.RECEIVE_NAME = (CRYPTO_ENC('normal', #{query}, ''))
AND OI.ITEM_NAME LIKE '%' || #{query} || '%'
AND OAOL.MANAGER_NM = (CRYPTO_ENC('normal', #{query}, ''))
ORDER BY OI.PAY_DATE DESC
)

/* saleson.shop.orderagency.OrderAgencyMapper.selectOrderAgencyOrderCnt 대행주문 목록 카운트 조회 */ SELECT COUNT(*) FROM G_ORDER_AGENCY_ORDER_LOG OAOL LEFT JOIN OP_ORDER O ON OAOL.ORDER_CODE = O.ORDER_CODE LEFT JOIN OP_ORDER_ITEM OI ON OI.ORDER_CODE = OAOL.ORDER_CODE AND OI.ORDER_SEQUENCE = OAOL.ORDER_SEQUENCE AND OI.ITEM_SEQUENCE = OAOL.ITEM_SEQUENCE LEFT JOIN OP_ORDER_SHIPPING_INFO OSI ON OI.ORDER_CODE = OSI.ORDER_CODE LEFT JOIN G_LOCGOV L ON OI.LOCGOV_CODE = L.LOCGOV_CODE WHERE 1=1
AND OAOL.MANAGER_ID = #{userId}
AND OI.PAY_DATE BETWEEN #{searchStartDate} || '000000' AND #{searchEndDate} || '235959'
AND OAOL.MANAGER_LCLGV_CD = #{locgovCode}
AND L.UPPER_LOCGOV_CODE = #{upperLocgovCode}
AND OAOL.MANAGER_LCLGV_CD = #{locgovCode}
AND OAOL.ORDER_CODE LIKE '%' || #{query} || '%'
AND O.BUYER_NAME = (CRYPTO_ENC('normal', #{query}, ''))
AND OSI.RECEIVE_NAME = (CRYPTO_ENC('normal', #{query}, ''))
AND OI.ITEM_NAME LIKE '%' || #{query} || '%'
AND OAOL.MANAGER_NM = (CRYPTO_ENC('normal', #{query}, ''))
